INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(9701, '1 Chronicles 1:15', '1 Chronicles', 1, 15, '&nbsp;حِوى، عرقى، سينى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9702, '1 Chronicles 1:16', '1 Chronicles', 1, 16, '&nbsp;اروادى، صمارى او حماتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9703, '1 Chronicles 1:17', '1 Chronicles', 1, 17, '&nbsp;دا د شيم اولاد دے: عيلام، اسور، ارفکسد، لود او آرام. د آرام اولاد عُوض، حُول، جتر او مسک وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9704, '1 Chronicles 1:18', '1 Chronicles', 1, 18, '&nbsp;ارفکسد د سِلح پلار وو او سِلح د عِبر پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9705, '1 Chronicles 1:19', '1 Chronicles', 1, 19, '&nbsp;د عِبر دوه زامن وُو، د يو نوم فلج چې مطلب يې تقسيم وو، ځکه چې د هغۀ په وخت کښې د دُنيا خلق تقسيم شول. او د بل نوم يُقطان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9706, '1 Chronicles 1:20', '1 Chronicles', 1, 20, '&nbsp;د يُقطان اولاد د الموداد، سلف، حصارماوت، اِراخ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9707, '1 Chronicles 1:21', '1 Chronicles', 1, 21, '&nbsp;هدورام، اُوزال، دِقله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9708, '1 Chronicles 1:22', '1 Chronicles', 1, 22, '&nbsp;عوبال، ابى‌مائيل، شيبا،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9709, '1 Chronicles 1:23', '1 Chronicles', 1, 23, '&nbsp;اوفير، حويله او يوباب. دا ټول د يُقطان اولاد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9710, '1 Chronicles 1:24', '1 Chronicles', 1, 24, '&nbsp;د شيم نه تر ابرام پورې نسب‌نامه داسې ده: شيم، ارفکسد، سِلح،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9711, '1 Chronicles 1:25', '1 Chronicles', 1, 25, '&nbsp;عِبر، فلج، رعو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9712, '1 Chronicles 1:26', '1 Chronicles', 1, 26, '&nbsp;سروګ، نحور، تارح،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9713, '1 Chronicles 1:27', '1 Chronicles', 1, 27, '&nbsp;او ابرام چې د اِبراهيم په نوم مشهور وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9714, '1 Chronicles 1:28', '1 Chronicles', 1, 28, '&nbsp;د اِبراهيم دوه زامن وُو، اِسحاق او اِسمٰعيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9715, '1 Chronicles 1:29', '1 Chronicles', 1, 29, '&nbsp;د اِسمٰعيل زامن د دولسو قبيلو مشران شول: نبايوت چې مشر وو، قيدار، ادبئيل، مِبسام،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9716, '1 Chronicles 1:30', '1 Chronicles', 1, 30, '&nbsp;مِشماع، دومه، مسا، حدد، تيما،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9717, '1 Chronicles 1:31', '1 Chronicles', 1, 31, '&nbsp;يطور، نفيس او قِدمه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9718, '1 Chronicles 1:32', '1 Chronicles', 1, 32, '&nbsp;د اِبراهيم يوه وينځه وه چې نوم يې قطوره وو، چې د هغې نه يې شپږ زامن پېدا شول: زمران، يُقسان، مِدان، ميديان، اسباق او سوخ. د يُقسان دوه زامن وُو: شيبا او ددان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9719, '1 Chronicles 1:33', '1 Chronicles', 1, 33, '&nbsp;د ميديان پينځۀ زامن وُو: عيفه، عِفر، حنوک، ابيداع او اِلدعا. دا ټول د قطوره اولاد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9720, '1 Chronicles 1:34', '1 Chronicles', 1, 34, '&nbsp;د اِبراهيم د زوئ اِسحاق زامن عِيسو او يعقوب وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9721, '1 Chronicles 1:35', '1 Chronicles', 1, 35, '&nbsp;د عِيسو زامن اليفز، رعواېل، يعوس، يعلام او قورح وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9722, '1 Chronicles 1:36', '1 Chronicles', 1, 36, '&nbsp;د اليفز اولاد دا وو: تيمان، اومر، صفو، جعتام، قنز او عماليق. د عماليق مور تمنع وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9723, '1 Chronicles 1:37', '1 Chronicles', 1, 37, '&nbsp;د رعواېل اولاد نحت، زارح، سمه او مِزه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9724, '1 Chronicles 1:51', '1 Chronicles', 1, 51, '&nbsp;د ادوم خلق په دې ډلو کښې تقسيم وُو: تمنع، علوه، يتيت،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9725, '1 Chronicles 1:52', '1 Chronicles', 1, 52, '&nbsp;اُهليبامه، ايله، فينون،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9726, '1 Chronicles 1:53', '1 Chronicles', 1, 53, '&nbsp;قنز، تيمان، مِبصار،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9727, '1 Chronicles 1:54', '1 Chronicles', 1, 54, '&nbsp;مجدِ‌اېل او عِرام.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9728, '1 Chronicles 2:1', '1 Chronicles', 2, 1, '&nbsp;د يعقوب دولس زامن وُو: روبين، شمعون، ليوى، يهوداه، يساکار، زبولون،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9729, '1 Chronicles 2:2', '1 Chronicles', 2, 2, '&nbsp;دان، يوسف، بنيامين، نفتالى، جاد او آشر.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9730, '1 Chronicles 2:3', '1 Chronicles', 2, 3, '&nbsp;د يهوداه ټول پينځۀ زامن وُو. د هغۀ د کنعانۍ ښځې بت‌سوع نه درې زامن وُو: عير، اونان او سيله. د هغۀ مشر زوئ عير دومره خراب وو چې مالِک خُدائ هغه ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9731, '1 Chronicles 2:4', '1 Chronicles', 2, 4, '&nbsp;د يهوداه د خپلې اِنږور تامار نه دوه زامن فارص او زارح وُو. نو د يهوداه ټول پينځۀ زامن وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9732, '1 Chronicles 2:5', '1 Chronicles', 2, 5, '&nbsp;د فارص دوه زامن حصرون او حمول وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9733, '1 Chronicles 2:6', '1 Chronicles', 2, 6, '&nbsp;د هغۀ د ورور زارح پينځۀ زامن وُو: زِمرى، ايتان، هيمان، کل‌کُول او دردع.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9734, '1 Chronicles 2:7', '1 Chronicles', 2, 7, '&nbsp;د زارح د اولاد نه يو کس د کرمى زوئ عکن په بنى اِسرائيلو باندې ځکه افت راوستلو چې کوم مالِ غنيمت خُدائ پاک ته وقف شوے وو نو په هغې کښې يې خيانت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9735, '1 Chronicles 2:8', '1 Chronicles', 2, 8, '&nbsp;د ايتان يو زوئ عزرياه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9736, '1 Chronicles 2:9', '1 Chronicles', 2, 9, '&nbsp;د حصرون درې زامن يرحمئيل، رام او کلوبى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9737, '1 Chronicles 2:10', '1 Chronicles', 2, 10, '&nbsp;د رام نه تر يَسى پورې نسب‌نامه داسې ده: رام، عمى‌نداب، نحشون چې دا د يهوداه د قبيلې يو مشر سړے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9738, '1 Chronicles 2:11', '1 Chronicles', 2, 11, '&nbsp;سلمون، بوعز،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9739, '1 Chronicles 2:12', '1 Chronicles', 2, 12, '&nbsp;عوبيد او يَسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9740, '1 Chronicles 2:13', '1 Chronicles', 2, 13, '&nbsp;د يَسى اووۀ زامن وُو، د عُمر په ترتيب باندې هغوئ داسې وُو: اِلياب، ابينداب، سِمعه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9741, '1 Chronicles 2:14', '1 Chronicles', 2, 14, '&nbsp;نتنى‌ايل، ردى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9742, '1 Chronicles 2:15', '1 Chronicles', 2, 15, '&nbsp;عوضم او داؤد.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9743, '1 Chronicles 2:16', '1 Chronicles', 2, 16, '&nbsp;د هغۀ دوه لوڼه ضروياه او ابى‌جيل هم وې. د يَسى د لور ضروياه درې زامن وُو: ابيشى، يوآب او عساهيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9744, '1 Chronicles 2:17', '1 Chronicles', 2, 17, '&nbsp;د هغۀ بلې لور ابى‌جيل د يتر سره وادۀ وکړو، چې د اِسمٰعيل د اولاد نه وو او د هغوئ يو زوئ پېدا شو چې نوم يې عماسا وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9745, '1 Chronicles 2:18', '1 Chronicles', 2, 18, '&nbsp;د حصرون زوئ کالب عزوبه وادۀ کړه او يوه لور يې ترې نه وشوله چې نوم يې يريعوت وو. د هغې درې زامن وُو: يشر، سوباب او اردون.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9746, '1 Chronicles 2:19', '1 Chronicles', 2, 19, '&nbsp;چې کله عزوبه مړه شوه نو کالب اِفراته وادۀ کړه او د هغوئ يو زوئ وشو چې نوم يې حُور وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9747, '1 Chronicles 2:20', '1 Chronicles', 2, 20, '&nbsp;د حُور زوئ اورى وو او د هغۀ نمسے بضلى‌اېل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9748, '1 Chronicles 2:21', '1 Chronicles', 2, 21, '&nbsp;کله چې حصرون د شپېتو کالو وو، نو هغۀ د مکير د لور سره وادۀ وکړو، چې د جِلعاد خور وه. د هغوئ يو زوئ وشو چې نوم يې سجوب وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9749, '1 Chronicles 2:22', '1 Chronicles', 2, 22, '&nbsp;او د سجوب يو زوئ وو چې نوم يې يائير وو. يائير د جِلعاد په علاقه کښې په درويشتو ښارونو باندې حکومت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9750, '1 Chronicles 2:23', '1 Chronicles', 2, 23, '&nbsp;خو د جسور او شام حکومتونو هلته شپېتۀ ښارونه فتح کړل، چې په دې کښې د يائير او قنات کلى او د دې نزدې ښارونه شامل وُو. هلته چې څومره خلق اوسېدل هغوئ د مکير اولاد وو. مکير د جِلعاد پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9751, '1 Chronicles 2:24', '1 Chronicles', 2, 24, '&nbsp;د حصرون د مرګ نه پس، د هغۀ زوئ کالب اِفرات وادۀ کړه، چې د هغۀ د پلار کونډه وه. د هغوئ يو زوئ وشو چې نوم يې اشور وو، چې دې د تقوع پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9752, '1 Chronicles 2:25', '1 Chronicles', 2, 25, '&nbsp;د حصرون د مشر زوئ يرحمئيل پينځۀ زامن وُو: د ټولو نه مشر رام وو او ورپسې بونه، اورن، عوضم او اخياه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9753, '1 Chronicles 2:28', '1 Chronicles', 2, 28, '&nbsp;د اونام دوه زامن سمى او يدع وُو، د سمى هم دوه زامن ندب او ابيسُور وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9754, '1 Chronicles 2:29', '1 Chronicles', 2, 29, '&nbsp;ابيسُور يوه ښځه وکړه چې نوم يې ابى‌خېل وو، د هغوئ دوه زامن اخبان او مولِد وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9755, '1 Chronicles 2:30', '1 Chronicles', 2, 30, '&nbsp;د ابيسُور د ورور ندب دوه زامن سلد او افائم وُو، خو د سلد اولاد نۀ وو او مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9756, '1 Chronicles 2:31', '1 Chronicles', 2, 31, '&nbsp;افائم د يسعى پلار وو، يسعى د سيسان پلار وو او سيسان د اخلى پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9757, '1 Chronicles 2:32', '1 Chronicles', 2, 32, '&nbsp;د سمى د ورور يدع دوه زامن يتر او يونتن وُو، خو يتر بغېر د زامنو نه مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9758, '1 Chronicles 2:33', '1 Chronicles', 2, 33, '&nbsp;د يونتن دوه زامن پلت او زازا وُو. دا ټول د يرحمئيل اولاد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9759, '1 Chronicles 2:34', '1 Chronicles', 2, 34, '&nbsp;د سيسان زامن نۀ وُو صِرف لوڼه يې وې. د هغۀ يو مِصرے نوکر وو چې نوم يې يرخع وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9760, '1 Chronicles 2:35', '1 Chronicles', 2, 35, '&nbsp;چې هغۀ له يې خپله يوه لور ورکړه چې وادۀ يې کړى. د هغوئ يو زوئ وو چې نوم يې عتى وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9761, '1 Chronicles 2:36', '1 Chronicles', 2, 36, '&nbsp;د عتى نه تر اليسمع پورې نسب‌نامه داسې ده: عتى، ناتن، زاباد،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9762, '1 Chronicles 2:37', '1 Chronicles', 2, 37, '&nbsp;افلال، عوبيد،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9763, '1 Chronicles 2:38', '1 Chronicles', 2, 38, '&nbsp;ياهُو، عزرياه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9764, '1 Chronicles 2:39', '1 Chronicles', 2, 39, '&nbsp;خلص، اِلعاسه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9765, '1 Chronicles 2:40', '1 Chronicles', 2, 40, '&nbsp;سِسمى، سلوم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9766, '1 Chronicles 2:41', '1 Chronicles', 2, 41, '&nbsp;يقمياه او اليسمع.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9767, '1 Chronicles 2:42', '1 Chronicles', 2, 42, '&nbsp;د يرحمئيل د ورور د کالب د مشر زوئ نوم ميسا وو. ميسا د زيف پلار وو، چې دې د مريسه پلار وو چې هغه د حبرون پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9768, '1 Chronicles 2:43', '1 Chronicles', 2, 43, '&nbsp;د حبرون څلور زامن وُو: قورح، تفوح، رِقم او سمع.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9769, '1 Chronicles 2:44', '1 Chronicles', 2, 44, '&nbsp;سمى د رحم پلار او د يُرقعام نيکۀ وو. د سمع ورور رِقم د سمى پلار وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9770, '1 Chronicles 2:45', '1 Chronicles', 2, 45, '&nbsp;چې سمى د معون پلار وو، او معون د بيت‌صور پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9771, '1 Chronicles 2:46', '1 Chronicles', 2, 46, '&nbsp;د کالب يوه وينځه وه چې نوم يې عيفه وو او د هغې نه يې درې نور زامن وُو: حاران، موضا او جازز. د حاران هم يو زوئ وو چې نوم يې جازز وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9772, '1 Chronicles 2:47', '1 Chronicles', 2, 47, '&nbsp;يهدى نومې يو سړے وو چې د هغۀ شپږ زامن وُو: رجم، يوتام، جسان، فِلِط، عيفه او شعف.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9773, '1 Chronicles 2:48', '1 Chronicles', 2, 48, '&nbsp;د کالب يوه وينځه معکه هم وه، چې د هغې نه يې دوه زامن وُو، شبر او تِرحنه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9774, '1 Chronicles 2:49', '1 Chronicles', 2, 49, '&nbsp;وروستو يې دوه نور زامن پېدا شول: شعف، چا چې د مدمنه ښار جوړ کړے وو، او سِوا، چا چې د مکبينه او جبعه ښارونه جوړ کړى وُو. د دې نه علاوه د کالب يوه لور وه چې نوم يې عکسه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9775, '1 Chronicles 2:50', '1 Chronicles', 2, 50, '&nbsp;دا هم د کالب اولاد وو. حُور د کالب او د هغۀ د ښځې اِفرات مشر زوئ وو. د حُور زوئ سوبل د قِريَت‌يعريم ښار جوړ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9776, '1 Chronicles 2:51', '1 Chronicles', 2, 51, '&nbsp;د هغۀ دوېم زوئ ساما چا چې د بيت‌لحم ښار جوړ کړے وو او د هغۀ درېم زوئ خارف چا چې د بيت‌جادر ښار جوړ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9777, '1 Chronicles 2:52', '1 Chronicles', 2, 52, '&nbsp;سوبل، چا چې د قِريَت‌يعريم ښار جوړ کړے وو، هغه د هرائى د خلقو او د هغه نيمو خلقو پلار نيکۀ وو چې څوک د منوخوت په ښار کښې اوسېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9778, '1 Chronicles 2:53', '1 Chronicles', 2, 53, '&nbsp;او کومې قبيلې چې په قِريَت‌يعريم کښې وې دا دى: اِتريان، فُوتيان، سماتيان او مِسراعيان. د صُرعه او استاول ښارونو خلق د دې قبيلو کسان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9779, '1 Chronicles 2:54', '1 Chronicles', 2, 54, '&nbsp;سلما د بيت‌لحم، د نطوفاتى، عطرات‌بيت‌يوآب او صُرعى د خلقو پلار نيکۀ وو، چې صُرعى په مانحت کښې د دوو ډلو نه يوه وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9780, '1 Chronicles 2:55', '1 Chronicles', 2, 55, '&nbsp;او کومې قبيلې چې په ليکلو کښې ماهِران وُو هغوئ په يعبيض کښې اوسېدل: هغوئ تِرعايان، سِمعيان او سوکاتيان وُو. هغوئ د حمات د قينيانو اولاد وو. حمات د ريکاب د خاندان پلار نيکۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9781, '1 Chronicles 3:4', '1 Chronicles', 3, 4, '&nbsp;دا شپږ واړه په حبرون کښې پېدا شوى وُو، چرته چې هغۀ اووۀ کاله او شپږ مياشتې بادشاهى وکړه. د هغې نه پس په يروشلم کښې هغۀ درې دېرش کاله حکومت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9782, '1 Chronicles 3:5', '1 Chronicles', 3, 5, '&nbsp;په يروشلم کښې چې د داؤد کوم زامن پېدا شوى وُو په هغوئ کښې سموع، سوباب، ناتن او سليمان شامل دى. د هغوئ مور بت‌‌سبع وه چې د عمى‌اېل لور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9783, '1 Chronicles 3:6', '1 Chronicles', 3, 6, '&nbsp;د هغۀ نور نهۀ زامن هم وُو: اِبحار، اليسوع، اليفلط،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9784, '1 Chronicles 3:7', '1 Chronicles', 3, 7, '&nbsp;نجه، نفج، يفيع،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9785, '1 Chronicles 3:8', '1 Chronicles', 3, 8, '&nbsp;اليسمع، اليدع او اليفلط.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9786, '1 Chronicles 3:9', '1 Chronicles', 3, 9, '&nbsp;د دې ټولو زامنو نه علاوه د داؤد د وينځو زامن هم وُو. د هغۀ يوه لور تامار هم وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9787, '1 Chronicles 3:10', '1 Chronicles', 3, 10, '&nbsp;دا د سليمان اولاد دے: سليمان، رحُبعام، ابياه، آسا، يهوسفط،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
