(9789, '1 Chronicles 3:12', '1 Chronicles', 3, 12, '&nbsp;امصياه، عُزياه، يوتام،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9790, '1 Chronicles 3:13', '1 Chronicles', 3, 13, '&nbsp;احاز، حزقياه، منسى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9791, '1 Chronicles 3:14', '1 Chronicles', 3, 14, '&nbsp;امون او يوسياه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9792, '1 Chronicles 3:15', '1 Chronicles', 3, 15, '&nbsp;د يوسياه څلور زامن د عُمر په ترتيب دا وُو: يوحانان، يهويقيم، صدقياه او يهوآخز.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9793, '1 Chronicles 3:16', '1 Chronicles', 3, 16, '&nbsp;د يهويقيم دوه زامن وُو: يهوياکين او صدقياه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9794, '1 Chronicles 3:17', '1 Chronicles', 3, 17, '&nbsp;دا د يهوياکين بادشاه اولاد دے، يهوياکين بابليانو قېدى بوتلے وو. د يهوياکين اووۀ زامن وُو: شلتى‌اېل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9795, '1 Chronicles 3:18', '1 Chronicles', 3, 18, '&nbsp;مُلکِرام، فداياه، شيناضر، يقمياه، هوسمع او ندبياه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9796, '1 Chronicles 3:19', '1 Chronicles', 3, 19, '&nbsp;د فداياه دوه زامن وُو، زرُبابل او سِمعى. زرُبابل د دوو زامنو پلار وو، مسلام او حننياه. او د هغۀ يوه لور سلوميت وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9797, '1 Chronicles 3:20', '1 Chronicles', 3, 20, '&nbsp;د هغۀ پينځۀ نور زامن وُو: حسوبه، اُهل، برکياه، حسدياه او يوسب‌حسد.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9798, '1 Chronicles 3:21', '1 Chronicles', 3, 21, '&nbsp;د حننياه دوه زامن فلطياه او يشعياه وُو. د يشعياه زوئ رفاياه وو، د رفاياه زوئ ارنان وو، د ارنان زوئ عبدياه وو او د عبدياه زوئ سکانياه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9799, '1 Chronicles 3:22', '1 Chronicles', 3, 22, '&nbsp;د سکانياه يو زوئ سمعياه او پينځۀ نمسى وُو: حطوش، اِجال، بريح، نعرياه او سافط.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9800, '1 Chronicles 3:23', '1 Chronicles', 3, 23, '&nbsp;د نعرياه درې زامن اليوعينى، حزقياه او عزريقام وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');